/// <summary>
/// MPJ_28155 UI builder for route update
/// </summary>
class METSalesOrderShipmentWorkbenchRouteUpdateUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField                                                 dialogFieldPrimaryRoute,dialogFieldRouteStop,dialogFieldPrimaryRouteToChange,dialogFieldRouteStopToChange;
    METSalesOrderShipmentWorkbenchRouteUpdateContract           dataContract;
    


   

}

Method.Source:
    /// <summary>
    /// post build
    /// </summary>
    public void postBuild()
    {
        super();
        dataContract    = this.dataContractObject() as METSalesOrderShipmentWorkbenchRouteUpdateContract;
        dialogFieldPrimaryRoute                = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmPrimaryRoute));
        dialogFieldPrimaryRouteToChange        = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmPrimaryRouteChange));
        dialogFieldPrimaryRouteToChange.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METSalesOrderShipmentWorkbenchRouteUpdateUIBuilder, primaryRouteLookup), this);

        dialogFieldRouteStop                = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmRouteStop));
        dialogFieldRouteStopToChange        = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmRouteStopChange));
     
        dialogFieldRouteStopToChange.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METSalesOrderShipmentWorkbenchRouteUpdateUIBuilder, routeStopLookup), this);

        dialogFieldPrimaryRoute.enabled(false);
        dialogFieldRouteStop.enabled(false);
    }

    /// <summary>
    /// primary route lookup
    /// </summary>
    /// <param name = "_ctrl">dialog control</param>
    protected void primaryRouteLookup(FormStringControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(SalesTable));

      
        sysTableLookup.addLookupfield(fieldNum(SalesTable, METRoute));
        queryBuildDataSource.addSortField(fieldnum(SalesTable, METRoute));
        queryBuildDataSource.addOrderByField(fieldnum(SalesTable, METRoute));
        queryBuildDataSource.orderMode(OrderMode::GroupBy);

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    ///  route stop lookup
    /// </summary>
    /// <param name = "_ctrl">dialog control</param>
    protected void routeStopLookup(FormIntControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(SalesTable));
        queryBuildDataSource.addRange(fieldNum(SalesTable, METRouteStopNum)).value(strFmt('>0'));

      
        queryBuildDataSource.addGroupByField(fieldnum(SalesTable, METRouteStopNum));
        sysTableLookup.addLookupfield(fieldNum(SalesTable, METRouteStopNum));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
